void main() {
  final antwort = jsonDecode(_antwortSeo) as Map<String, dynamic>;

  group('Die Seitenkarten lassen sich lesen', () {
    test('jede Karte hat die erwarteten Felder', () {
      final seiten = webListe(antwort['seiten']);
      expect(seiten, isNotEmpty);
      for (final s in seiten) {
        expect('${s['pfad']}', startsWith('/'));
        expect(webZahl(s['note']), inInclusiveRange(0, 100));
        // Alles ueber webZahl lesen: die Werte kommen als Zeichenkette.
        expect(webZahl(s['woerter']), greaterThanOrEqualTo(0));
        expect(webZahl(s['groesse_gz']), greaterThan(0));
      }
    });

    test('einfache Spalten kommen als Zahl — anders als die SUM()-Endpunkte', () {
      final erste = webListe(antwort['seiten']).first;
      expect(erste['note'], isA<int>(),
          reason: 'einfache Spalte, deshalb typisiert');
      // Der Client darf sich darauf trotzdem nicht verlassen.
      expect(webZahl(erste['note']), greaterThan(0));
      expect(webZahl('${erste['note']}'), webZahl(erste['note']));
    });

    test('die schwaechste Seite steht vorn', () {
      final noten = webListe(antwort['seiten']).map((s) => webZahl(s['note'])).toList();
      expect(noten.first, lessThanOrEqualTo(noten.last));
    });

    test('Schnitt und Waisenzahl sind da', () {
      expect(webKarte(antwort['schnitt']), isNotEmpty);
      expect(webZahl(webKarte(antwort['schnitt'])['note']), inInclusiveRange(0, 100));
      expect(antwort['waisen'], isNotNull);
    });

    test('der Hinweis zu LCP/INP/CLS fehlt nicht', () {
      // ⚠️ Er ist kein Schmuck: ohne ihn liest jemand die Antwortzeit als
      // Ladeerfahrung, und die ist etwas anderes.
      expect('${antwort['hinweis']}', contains('LCP'));
    });
  });
}
